CREATE SCHEMA IF NOT EXISTS app;

CREATE TABLE app.events (
  id BIGSERIAL,
  created_at TIMESTAMPTZ NOT NULL,
  event_type TEXT NOT NULL,
  payload JSONB DEFAULT '{}'
);

CREATE INDEX idx_events_created_at ON app.events (created_at);

INSERT INTO app.events (created_at, event_type, payload)
SELECT
  '2026-01-01'::timestamptz + (i || ' hours')::interval,
  (ARRAY['pageview', 'click', 'purchase'])[1 + (i % 3)],
  '{}'::jsonb
FROM generate_series(0, 719) AS i;

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { avoidsSelectStarQueries, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function date_range_query_under_200ms(ctx: AssertionContext): Promise<AssertionResult> {
  const start = Date.now();
  await ctx.pg.query(
    "SELECT count(*) FROM app.events WHERE created_at >= '2026-01-15' AND created_at < '2026-01-16'",
  );
  const elapsed = Date.now() - start;
  const passed = elapsed < 200;
  return {
    passed,
    message: passed ? "Date range query under 200ms." : `Query took ${elapsed}ms.`,
    details: { elapsedMs: elapsed },
  };
}

export async function avoids_select_star_queries(): Promise<AssertionResult> {
  return avoidsSelectStarQueries();
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function events_table_exists(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query(
    "SELECT count(*) AS n FROM information_schema.tables WHERE table_schema = 'app' AND table_name = 'events'",
  );
  const count = Number(result.rows[0]?.n ?? 0);
  const passed = count === 1;
  return {
    passed,
    message: passed ? "Events table exists." : `Expected 1 table, got ${count}.`,
    details: { count },
  };
}

export async function table_has_rows(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query("SELECT count(*) AS n FROM app.events");
  const count = Number(result.rows[0]?.n ?? 0);
  const passed = count > 0;
  return {
    passed,
    message: passed ? "Table has rows." : "Table is empty.",
    details: { count },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function row_count_preserved(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query("SELECT count(*) AS n FROM app.events");
  const count = Number(result.rows[0]?.n ?? 0);
  const passed = count >= 720;
  return {
    passed,
    message: passed ? "Row count preserved." : `Expected at least 720 rows, got ${count}.`,
    details: { count },
  };
}

